import networkx as nx

edges = [
    (0, 7), (0, 11), (0, 13),
    (1, 7), (1, 8), (1, 12),
    (2, 8), (2, 9), (2, 13),
    (3, 7), (3, 9), (3, 10),
    (4, 8), (4, 10), (4, 11),
    (5, 9), (5, 11), (5, 12),
    (6, 10), (6, 12), (6, 13)
]

G = nx.Graph()
G.add_nodes_from(range(14))
G.add_edges_from(edges)

# Verify girth properly
def get_girth(G):
    for length in range(3, G.number_of_nodes() + 1):
        for cycle in nx.simple_cycles(G.to_directed()):
            if len(cycle) == length:
                return length
    return float('inf')

# Actually, simple_cycles is for directed graphs.
# For undirected, we can use nx.find_cycle or just check all cycles.
# A better way for girth:
def girth(G):
    g = float('inf')
    for node in G.nodes():
        # BFS to find shortest cycle containing node
        dist = {node: 0}
        parent = {node: None}
        queue = [node]
        while queue:
            u = queue.pop(0)
            for v in G.neighbors(u):
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    g = min(g, dist[u] + dist[v] + 1)
    return g

print(f"Girth: {girth(G)}")
print(f"Edges: {list(G.edges())}")
